package be.winnetrie.mod.simpleserverutilities.moderation;
import java.util.ArrayList;import java.util.List;import java.util.UUID;import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.SimpleContainer;import net.minecraft.world.SimpleMenuProvider;import net.minecraft.world.item.ItemStack;
public final class PlayerInventoryAdminService{private PlayerInventoryAdminService(){}public static void open(ServerPlayer admin,String raw,String rawMode){UUID id=SimpleServerUtilities.MODERATION.resolvePlayer(raw);if(id==null)throw new IllegalArgumentException("Player name or UUID was not found.");if(id.equals(admin.getUUID()))throw new IllegalArgumentException("Close the admin menu and use your normal inventory to edit yourself safely.");String mode="ender".equalsIgnoreCase(rawMode)?"ender":"inventory";ServerPlayer online=admin.level().getServer().getPlayerList().getPlayer(id);String name=online==null?SimpleServerUtilities.MODERATION.name(id):online.getName().getString();PlayerInventorySnapshot snapshot=online==null?SimpleServerUtilities.MODERATION.inventories().get(id):PlayerInventorySnapshot.capture(online);if(snapshot==null)throw new IllegalArgumentException("No offline inventory snapshot exists yet. The player must join once after this update.");int size=mode.equals("ender")?PlayerInventoryAdminMenu.ENDER_SLOTS:PlayerInventoryAdminMenu.INVENTORY_SLOTS;SimpleContainer target=new SimpleContainer(size);List<ItemStack> values=mode.equals("ender")?snapshot.enderStacks(admin.level().registryAccess(),size):snapshot.inventoryStacks(admin.level().registryAccess(),size);for(int i=0;i<Math.min(size,values.size());i++)target.setItem(i,values.get(i).copy());Runnable saver=()->save(admin,id,name,mode,target,online);admin.openMenu(new SimpleMenuProvider((containerId,inventory,ignored)->new PlayerInventoryAdminMenu(containerId,inventory,target,id.toString(),name,mode,saver),Component.literal((mode.equals("ender")?"Ender chest — ":"Inventory — ")+name)),buf->{buf.writeVarInt(size);buf.writeUtf(id.toString(),64);buf.writeUtf(name,64);buf.writeUtf(mode,16);});}
 private static void save(ServerPlayer admin,UUID id,String name,String mode,SimpleContainer target,ServerPlayer originalOnline){SimpleServerUtilities.SERVER_OPERATIONS.audit(admin,"moderation.inventory_edit",name,mode);ArrayList<ItemStack> values=new ArrayList<>();for(int i=0;i<target.getContainerSize();i++)values.add(target.getItem(i).copy());ServerPlayer online=admin.level().getServer().getPlayerList().getPlayer(id);if(online!=null){if(mode.equals("ender")){online.getEnderChestInventory().clearContent();for(int i=0;i<Math.min(values.size(),online.getEnderChestInventory().getContainerSize());i++)online.getEnderChestInventory().setItem(i,values.get(i));online.getEnderChestInventory().setChanged();}else{online.getInventory().clearContent();for(int i=0;i<Math.min(values.size(),online.getInventory().getContainerSize());i++)online.getInventory().setItem(i,values.get(i));online.getInventory().setChanged();online.containerMenu.broadcastChanges();}SimpleServerUtilities.MODERATION.inventories().capture(online);return;}PlayerInventorySnapshot snapshot=SimpleServerUtilities.MODERATION.inventories().getOrCreate(id,name);if(mode.equals("ender"))snapshot.setEnderStacks(admin.level().registryAccess(),values);else snapshot.setInventoryStacks(admin.level().registryAccess(),values);SimpleServerUtilities.MODERATION.inventories().markModified(id,snapshot,true);}
}
